// ════════════════════════════════════════════════════════════════════════
// WF2b · Step 6 "Sentiment Analysis + Patient Match" — FOUNDRY IQ EDITION
// v3 — `intents` as array of {type, search} objects (API shape verified).
// ════════════════════════════════════════════════════════════════════════
export const code = async (inputs) => {
  const event       = inputs.event      || {};
  const patients    = Array.isArray(inputs.patients)   ? inputs.patients   : [];
  const optOutList  = Array.isArray(inputs.optOutList) ? inputs.optOutList : [];
  const foundryKey  = inputs.foundryKey || '';
  const searchUrl   = (inputs.searchUrl || '').replace(/\/+$/, '');
  const searchKey   = inputs.searchKey  || '';
  const kbName      = inputs.kbName     || 'cliniccare-kb';

  const queueId    = event['A'] || '';
  const waMsgId    = event['B'] || '';
  const fromPhone  = (event['C'] || '').toString().trim();
  const eventType  = (event['D'] || '').toString().toLowerCase().trim();
  const rawPayload = event['E'] || '{}';

  const baseReturn = (extra) => ({
    action: 'status_update', sentiment: 'unknown', patientStatus: 'status_update',
    messageText: '', fromPhone, fromPhoneNorm: '', patientName: 'Unknown',
    clinicId: '', corrId: '', patientRow: '', queueId, waMsgId, patientId: '',
    aiUsed: false, urgency: 0, symptom: '', confidence: 0, aiReasoning: '',
    iqGrounded: false, iqCitations: [],
    debugError: '', eventType, ...extra
  });

  if (eventType !== 'incoming_message' && eventType !== 'message') {
    return baseReturn({ action: 'status_update' });
  }

  let messageText = '';
  try {
    if (rawPayload.startsWith('{')) {
      const parsed = JSON.parse(rawPayload);
      messageText = parsed?.entry?.[0]?.changes?.[0]?.value?.messages?.[0]?.text?.body || '';
    } else { messageText = rawPayload; }
  } catch(e) { messageText = rawPayload || ''; }

  const normalize = (p) => {
    let s = p.toString().replace(/[^0-9]/g, '');
    if (s.startsWith('0091')) s = s.slice(2);
    if (s.length === 10) s = '91' + s;
    return s;
  };
  const fromPhoneNorm = normalize(fromPhone);
  const lower = messageText.toLowerCase();

  const wrongKws = ['wrong number','galat number','yeh kaun','kaun hai','who is this'];
  if (wrongKws.some(k => lower.includes(k))) {
    return baseReturn({ action: 'WRONG_NUMBER', patientStatus: 'wrong_number', sentiment: 'wrong_number', messageText, fromPhoneNorm });
  }

  const patient = patients.find(p => {
    const pv = p['values'] || p;
    return normalize((pv['F'] || '').toString()) === fromPhoneNorm;
  });
  if (!patient) {
    return baseReturn({ action: 'unmatched', patientStatus: 'unmatched', messageText, fromPhoneNorm });
  }

  const pv          = patient['values'] || patient;
  const patientRow  = patient['row']  || '';
  const corrId      = pv['B'] || '';
  const clinicId    = pv['C'] || '';
  const patientName = pv['D'] || 'Patient';
  const patientId   = pv['A'] || '';

  const optOutKws = ['stop','band karo','mat bhejo','remove','unsubscribe','hatao','रोको','बंद करो'];
  if (optOutKws.some(k => lower.includes(k))) {
    return {
      action: 'opt_out', sentiment: 'opt_out', patientStatus: 'opted_out',
      messageText, fromPhone, fromPhoneNorm, patientName, clinicId, corrId,
      patientRow, queueId, waMsgId, patientId,
      aiUsed: false, urgency: 0, symptom: '', confidence: 1, aiReasoning: 'keyword opt-out',
      iqGrounded: false, iqCitations: [], debugError: ''
    };
  }

  let debugError = '';

  // ── ① FOUNDRY IQ · agentic retrieval (intents = [{type, search}, …]) ──
  let iqContext = '';
  let iqCitations = [];
  if (searchUrl && searchKey && messageText) {
    try {
      const iqResp = await fetch(
        `${searchUrl}/knowledgebases/${kbName}/retrieve?api-version=2026-05-01-preview`,
        {
          method: 'POST',
          headers: { 'api-key': searchKey, 'Content-Type': 'application/json' },
          body: JSON.stringify({
            intents: [
              { type: "semantic", search: `Patient ${patientName} (id ${patientId}) replied after treatment: "${messageText}". Find this patient's treatment record and the clinic protocol that applies to these symptoms at this point in their recovery timeline.` },
              { type: "semantic", search: `${patientName} ${patientId} treatment history` },
              { type: "semantic", search: `protocol for symptom: ${messageText}` }
            ]
          })
        }
      );
      if (iqResp.ok) {
        const iq = await iqResp.json();
        const blocks = (iq?.response || []).flatMap(r => r?.content || []);
        const rawTexts = blocks.map(b => b?.text || '').filter(Boolean);
        const pieces = [];
        for (const t of rawTexts) {
          try {
            const arr = JSON.parse(t);
            if (Array.isArray(arr)) {
              for (const x of arr) { if (x && typeof x.content === 'string') pieces.push(x.content); }
              continue;
            }
          } catch (_) {}
          pieces.push(t);
        }
        iqContext = pieces.join('\n\n').slice(0, 1800);
        const refs = iq?.references || [];
        iqCitations = refs.slice(0, 5).map(r => {
          const t = r?.sourceData?.title || r?.docKey || r?.id || r?.blobUrl || 'kb';
          return t.toString().split('/').pop();
        });
        if (!iqCitations.length && iqContext) {
          const found = [];
          if (/Patient Treatment History/i.test(iqContext)) found.push('patient_history.md');
          if (/Post-Treatment Care Protocols/i.test(iqContext)) found.push('clinic_protocols.md');
          iqCitations = found;
        }
      } else {
        debugError += `IQ HTTP ${iqResp.status}: ${(await iqResp.text()).slice(0, 200)} | `;
      }
    } catch (e) {
      debugError += 'IQ FETCH: ' + e.message + ' | ';
    }
  } else if (!searchUrl || !searchKey) {
    debugError += 'IQ not configured | ';
  }
  const iqGrounded = iqContext.length > 0;

  // ── ② MICROSOFT FOUNDRY · DeepSeek-V3.2 — grounded reasoning ─────────
  let aiSentiment = null, aiUsed = false;
  let urgency = 0, symptom = '', confidence = 0, aiReasoning = '';

  if (foundryKey && messageText) {
    try {
      const groundingBlock = iqGrounded
        ? `GROUNDED CONTEXT — retrieved by Foundry IQ from the clinic's knowledge base (patient history + protocols). Base your timeline/severity judgment on THIS, and reference it in "reasoning":\n${iqContext}`
        : `(No grounded context available this run — reason conservatively; when in doubt, escalate.)`;

      const aiResp = await fetch(
        'https://cliniccare-resource.services.ai.azure.com/openai/v1/chat/completions',
        {
          method: 'POST',
          headers: { 'api-key': foundryKey, 'Content-Type': 'application/json' },
          body: JSON.stringify({
            model: 'DeepSeek-V3.2',
            messages: [
              { role: 'system', content:
`You are a reasoning agent for an Indian medical clinic's WhatsApp follow-up system. The patient just replied to a post-treatment check-in.

${groundingBlock}

Return a STRICT JSON object — no markdown, no extra text — with these keys:
{
  "sentiment": "positive" | "negative" | "neutral" | "mixed" | "opt_out",
  "urgency":   0 | 1 | 2 | 3,
  "symptom":   "<short phrase, or empty string>",
  "action":    "send_review" | "send_empathy" | "send_empathy_and_alert_doctor" | "no_action" | "opt_out",
  "confidence":0.0 to 1.0,
  "reasoning": "<one short sentence why — cite the patient's treatment/protocol from the grounded context when used>"
}

Rules:
• "mixed" = gratitude AND a concern in the same message. Treat as warning, NOT positive.
• Use the grounded patient history: judge symptoms against WHERE the patient is in their expected recovery timeline.
• urgency 0 none · 1 mild/expected · 2 serious (worsening, persistent, outside expected timeline) · 3 emergency.
• If urgency ≥ 2 OR sentiment is "negative" or "mixed" → action MUST be "send_empathy_and_alert_doctor".
• If sentiment is clearly "positive" with no symptom → action = "send_review".
• If confidence < 0.7 → action = "no_action" (human will review).
• Read meaning, not keywords.` },
              { role: 'user', content: messageText }
            ],
            response_format: { type: 'json_object' },
            max_tokens: 300, temperature: 0.1
          })
        }
      );

      if (aiResp.ok) {
        const aiData = await aiResp.json();
        const raw = (aiData?.choices?.[0]?.message?.content || '').trim();
        try {
          const parsed = JSON.parse(raw);
          const map = { positive:'POSITIVE', negative:'NEGATIVE', neutral:'NEUTRAL', mixed:'NEGATIVE', opt_out:'OPT_OUT' };
          aiSentiment = map[(parsed.sentiment || '').toLowerCase()] || null;
          urgency     = Number.isFinite(parsed.urgency) ? Math.min(3, Math.max(0, parsed.urgency)) : 0;
          symptom     = (parsed.symptom || '').toString().slice(0, 80);
          confidence  = Number.isFinite(parsed.confidence) ? Math.min(1, Math.max(0, parsed.confidence)) : 0;
          aiReasoning = (parsed.reasoning || '').toString().slice(0, 200);
          if (iqGrounded) aiReasoning = `[IQ✓ ${iqCitations.join(', ').slice(0, 60)}] ` + aiReasoning;
          if (confidence < 0.7 && aiSentiment !== 'OPT_OUT') {
            aiSentiment = 'NEUTRAL';
            aiReasoning = '[low_confidence→human_review] ' + aiReasoning;
          }
          if (aiSentiment) aiUsed = true;
          else debugError += 'Bad AI sentiment: ' + (parsed.sentiment || '');
        } catch (pe) {
          debugError += 'JSON parse error: ' + pe.message + ' | raw: ' + raw.slice(0, 200);
        }
      } else {
        debugError += `HTTP ${aiResp.status}: ${(await aiResp.text()).slice(0, 300)}`;
      }
    } catch(e) { debugError += 'FETCH ERROR: ' + e.message; }
  } else {
    debugError += foundryKey ? 'No messageText' : 'No foundryKey';
  }

  // ── ③ Keyword fallback ──
  let finalSentiment = aiSentiment;
  if (!finalSentiment) {
    const pos = ['dard kam','dard nahi','ठीक','अच्छा','बेहतर','सुधार','better','good','great','fine','okay','ok','well','perfect','theek','shukriya','thank','thanks','recovered','comfortable','no pain','feeling good','👍','😊','✅','kam ho gaya','aram hai','relief'];
    const neg = ['aur dard hai','bahut dard','dard badh','dard zyada','तकलीफ','दिक्कत','खराब','सूजन','बुखार','समस्या','hurt','worse','fever','bleeding','swelling','emergency','not okay','not good','getting worse','nahi theek','theek nahi'];
    const isPos = pos.some(k => lower.includes(k) || messageText.includes(k));
    const isNeg = !isPos && neg.some(k => lower.includes(k) || messageText.includes(k));
    finalSentiment = isNeg ? 'NEGATIVE' : (isPos ? 'POSITIVE' : 'NEUTRAL');
  }

  const sentimentMap = {
    'POSITIVE': { sentiment: 'positive', patientStatus: 'replied_positive' },
    'NEGATIVE': { sentiment: 'negative', patientStatus: 'replied_negative' },
    'NEUTRAL':  { sentiment: 'neutral',  patientStatus: 'replied_neutral'  },
    'OPT_OUT':  { sentiment: 'opt_out',  patientStatus: 'opted_out'        }
  };
  const result = sentimentMap[finalSentiment] || sentimentMap['NEUTRAL'];

  return {
    action: finalSentiment === 'OPT_OUT' ? 'opt_out' : 'route',
    sentiment: result.sentiment,
    patientStatus: result.patientStatus,
    messageText, fromPhone, fromPhoneNorm, patientName,
    clinicId, corrId, patientRow, queueId, waMsgId, patientId,
    aiUsed, urgency, symptom, confidence, aiReasoning,
    iqGrounded, iqCitations, debugError
  };
};
